const storeKey='capimimo-purchases-v1';
const secret=bytes=>Array.from(crypto.getRandomValues(new Uint8Array(bytes)),n=>n.toString(16).padStart(2,'0')).join('');
export function initBillingClient({getState,beforeCheckout=async()=>{}}){
 let config={mode:'offline',checkoutReady:false},records=[];try{records=JSON.parse(localStorage.getItem(storeKey)||'[]');if(!Array.isArray(records))records=[];}catch{}
 const save=()=>{localStorage.setItem(storeKey,JSON.stringify(records));};
 const notify=()=>document.dispatchEvent(new CustomEvent('billing:change'));
 const ready=fetch('/api/billing/config',{cache:'no-store'}).then(async response=>{if(response.ok&&response.headers.get('content-type')?.includes('application/json'))config=await response.json();notify();return config;}).catch(()=>config);
 async function request(path,record,{method='GET',body,headers={}}={}){const response=await fetch(path,{method,headers:{...(record?{Authorization:'Bearer '+record.accessKey}:{}),...(body&&!(body instanceof Blob)?{'Content-Type':'application/json'}:{}),...headers},body:body instanceof Blob?body:body?JSON.stringify(body):undefined,cache:'no-store'});const result=await response.json().catch(()=>({error:'Resposta indisponível.'}));if(!response.ok)throw Error(result.error||'Não foi possível concluir agora.');return result;}
 function find(draftId=getState().draftId){return records.filter(r=>r.draftId===draftId&&r.mode===config.mode).sort((a,b)=>(b.status==='approved')-(a.status==='approved')||b.createdAt-a.createdAt)[0];}
 async function refresh(record=find(),sync=false){if(!record?.id)return null;const result=await request('/api/orders/'+record.id+(sync?'/sync':''),record,sync?{method:'POST',body:{}}:{});Object.assign(record,result);save();notify();return record;}
 async function checkout(planId,email=''){
  await ready;if(!config.checkoutReady)throw Error('O checkout ainda está em configuração.');await beforeCheckout();const state=getState(),approved=records.find(r=>r.draftId===state.draftId&&r.planId===planId&&r.mode===config.mode&&r.status==='approved');if(approved){await refresh(approved);if(approved.status==='approved')return approved;}let record=records.find(r=>r.draftId===state.draftId&&r.planId===planId&&r.mode===config.mode&&['pending','preparing'].includes(r.status));
  if(!record){record={draftId:state.draftId,planId,mode:config.mode,accessKey:secret(32),idempotencyKey:secret(16),createdAt:Date.now(),status:'pending'};records.push(record);save();}
  const result=await request('/api/checkout',record,{method:'POST',body:{planId,draftId:record.draftId,idempotencyKey:record.idempotencyKey,email}});Object.assign(record,result);save();notify();return record;
 }
 async function requirePurchase(format=getState().format,draftId=getState().draftId){await ready;if(!config.checkoutReady&&config.mode==='offline')return true;const record=find(draftId);if(!record?.id){document.dispatchEvent(new CustomEvent('billing:required',{detail:{format}}));return false;}await refresh(record);if(record.status!=='approved'||!config.plans?.[record.planId]?.formats.includes(format)){document.dispatchEvent(new CustomEvent('billing:required',{detail:{format}}));return false;}return true;}
 async function publish(data,blob,onProgress=()=>{}){await ready;const record=find(data.draftId);if(!record?.id||!await requirePurchase(data.format,data.draftId))throw Error('Confirme a compra deste presente antes de publicar.');if(blob.size>config.maxArchiveBytes)throw Error('O presente passou de '+Math.round(config.maxArchiveBytes/1024/1024)+' MB. Reduza fotos ou áudio.');let upload=blob,encoding='identity';if(typeof CompressionStream==='function'){const zipped=await new Response(blob.stream().pipeThrough(new CompressionStream('gzip'))).blob();if(zipped.size<blob.size){upload=zipped;encoding='gzip';}}
  onProgress({stage:'upload',bytes:upload.size,original:blob.size});const result=await request('/api/orders/'+record.id+'/publish',record,{method:'PUT',body:upload,headers:{'Content-Type':encoding==='gzip'?'application/gzip':'text/html; charset=utf-8','X-Gift-Encoding':encoding,'X-Gift-Format':data.format,'X-Gift-Recipient':encodeURIComponent(data.recipient||''),'X-Draft-Id':data.draftId,'X-Gift-Revision':String(record.delivery?.revision||0)}});Object.assign(record,result);save();notify();return record.delivery;
 }
 async function guests(){const record=find();if(!record?.id)return[];return(await request('/api/orders/'+record.id+'/guests',record)).guests;}
 async function addGuest(name,allowedCount){const record=find();if(!record?.id)throw Error('Compra não encontrada.');const result=await request('/api/orders/'+record.id+'/guests',record,{method:'POST',body:{name,allowedCount}});record.guestLinks??={};record.guestLinks[result.id]=result.url;save();return result;}
 function backup(){return new Blob([JSON.stringify({type:'capimimo-purchase-access',version:1,orders:records},null,2)],{type:'application/json'});}
 async function restore(file){if(file.size>256*1024)throw Error('Arquivo de acesso inválido.');const payload=JSON.parse(await file.text());if(payload.type!=='capimimo-purchase-access'||!Array.isArray(payload.orders))throw Error('Arquivo de acesso inválido.');const restored=[];for(const value of payload.orders){if(!/^[a-f0-9]{32}$/.test(value.id||'')||!/^[a-f0-9]{64}$/.test(value.accessKey||''))continue;const record={id:value.id,accessKey:value.accessKey,guestLinks:value.guestLinks||{},createdAt:Date.now()};await refresh(record);const old=records.findIndex(r=>r.id===record.id);if(old>=0)records[old]=record;else records.push(record);restored.push(record);}if(!restored.length)throw Error('Nenhuma compra válida encontrada neste arquivo.');save();notify();return restored;}
 async function readPublished(record){await refresh(record);if(!record.delivery||record.status!=='approved')throw Error('Este presente ainda não foi publicado.');const response=await fetch('/api/presents/'+record.delivery.id+'/download',{cache:'no-store'});if(!response.ok)throw Error('Não foi possível recuperar o presente.');const document=new DOMParser().parseFromString(await response.text(),'text/html'),script=document.querySelector('#capimimo-payload');if(!script)throw Error('Este arquivo pode ser visualizado, mas não tem dados de edição.');return JSON.parse(script.textContent);}
 return{ready,get config(){return config;},find,get:id=>records.find(r=>r.id===id),list:()=>records.map(r=>({id:r.id,draftId:r.draftId,planId:r.planId,status:r.status,delivery:r.delivery,mode:r.mode})),refresh,checkout,requirePurchase,publish,guests,addGuest,backup,restore,readPublished,guestLink:id=>find()?.guestLinks?.[id]};
}
